def _load_or_build():
    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            if len(data) >= 8000 and all("question" in q and "options" in q and "correct_idx" in q for q in data[:100]):
                return data
        except Exception:
            pass
    return []

